(()=>{(async function(){let a=await canvasGet("/api/v1/courses/"+ENV.COURSE_ID+"/assignment_groups?include[]=assignments"),d={};for(let n in a){let e=a[n],s=e.id,t={};for(let r in e.assignments){let i=e.assignments[r],o=i.id;i.quiz_id!==void 0&&(o=i.quiz_id),t[o]=i.id}d[s]=t}let u=await canvasGet("/api/v1/courses/"+ENV.COURSE_ID+"/modules?include[]=items&include[]=content_details"),l=[];for(let n in u){let e=u[n];for(let s in e.items){let t=e.items[s];t.content_id!==void 0&&l.push(t.content_id)}}$(".assignment_group").each(function(){let n=$(this),e=n.find("ul.al-options"),s=$('<a class="reorder_group icon-collection ui-corner-all" aria-label="Sort Assignment Group" id="ui-id-7" tabindex="-1" role="menuitem">Sort Items</a>'),t=$('<li class="ui-menu-item" role="presentation"></li>');t.append(s);let r=n.attr("data-id"),i=d[r],o="";for(let m in l){let g=l[m];g in i&&(m>0&&(o+=","),o+=i[g])}s.click(function(){$.post("/courses/"+ENV.COURSE_ID+"/assignment_groups/"+r+"/reorder",{order:o}),location.reload()}),e.append(t)})})();})();
